import React from 'react';
import Image from 'next/image';
import type { AiTakeoverPlan } from '@/types/app-shell';

type HeroSectionProps = {
  takeoverPlan?: AiTakeoverPlan;
};

export function HeroSection({ takeoverPlan }: HeroSectionProps) {
  const aiActive = Boolean(takeoverPlan?.enabled);
  const heading = aiActive
    ? takeoverPlan?.headline || 'RAYAY is actively optimizing product visibility'
    : 'One command center for ONBT across Base and Arbitrum.';
  const subline = aiActive
    ? takeoverPlan?.subline || 'Adaptive visuals and focused feature guidance are now enabled by RAYAY.'
    : 'Trade, bridge, stake, and govern with real-time telemetry and contract-safe execution flows.';

  return (
    <section className={`brand-hero hero-graphic mb-5 rounded-3xl p-4 sm:p-6 ${aiActive ? 'takeover-glow takeover-pulse' : ''}`}>
      <span className="mesh-overlay" aria-hidden="true" />
      <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-6">
        <div className="space-y-3 reveal-up stagger-1">
          <div className="flex flex-wrap items-center gap-2">
            <p className="inline-flex items-center rounded-full border border-slate-900/15 bg-white/95 px-3 py-1 font-['IBM_Plex_Mono'] text-[10px] font-semibold uppercase tracking-[0.16em] text-slate-700">
              LayerZero V2 Omnichain Interface
            </p>
            {aiActive && (
              <p className="inline-flex items-center rounded-full border border-sky-500/40 bg-sky-500/10 px-3 py-1 font-['IBM_Plex_Mono'] text-[10px] font-semibold uppercase tracking-[0.16em] text-sky-800">
                RAYAY Visibility Mode
              </p>
            )}
          </div>
          <h2 className="brand-display max-w-3xl text-3xl font-extrabold leading-[1.02] text-slate-900 sm:text-[3.25rem]">
            {heading}
          </h2>
          <p className="max-w-2xl text-sm text-slate-600 sm:text-lg">
            {subline}
          </p>
        </div>

        <div className="reveal-up stagger-2 grid grid-cols-1 gap-3 text-xs sm:grid-cols-3 sm:text-sm lg:max-w-[520px]">
          <div className="motion-card rounded-2xl border border-slate-900/12 bg-white/95 px-4 py-3">
            <p className="text-slate-500">Execution Hub</p>
            <p className="font-['IBM_Plex_Mono'] font-semibold text-slate-900">Base 8453</p>
          </div>
          <div className="motion-card rounded-2xl border border-slate-900/12 bg-white/95 px-4 py-3">
            <p className="text-slate-500">Settlement Route</p>
            <p className="font-['IBM_Plex_Mono'] font-semibold text-slate-900">Arbitrum 42161</p>
          </div>
          <div className="motion-card rounded-2xl border border-slate-900/12 bg-white/95 px-4 py-3">
            <p className="text-slate-500">Runtime Stack</p>
            <p className="font-['IBM_Plex_Mono'] font-semibold text-slate-900">OnchainKit + Wagmi</p>
          </div>
        </div>
      </div>

      <div className="reveal-up stagger-3 pointer-events-none mt-3 hidden items-center justify-end lg:flex">
        <div className="hero-orb relative flex h-14 w-14 items-center justify-center rounded-full border border-slate-900/12 bg-white/85 backdrop-blur-sm">
          <Image
            src="/branding/onabat-logo-light.png"
            alt="ONabat"
            width={32}
            height={32}
            className="h-8 w-8 object-contain logo-float"
            priority
          />
          <span className="hero-ring absolute inset-[-6px] rounded-full border border-cyan-300/50" />
        </div>
      </div>
    </section>
  );
}
